1	import { finding, lineOf } from './finding.mjs';
2	
3	// Every `.claudinite/...` path this repo spells in its OWN files must still
4	// resolve inside the mount. The canon relays out its own layout on each baseline
5	// (this repo's copy has already moved through mount/, then shared/, then
6	// shared/engine/hooks/), and nothing upstream rewrites the references we keep on
7	// our side. The canon `claudinite-isolation` barrier notices only THAT a file
8	// names a mount path, never whether the path is real — and CLAUDE.md carries an
9	// `accept` entry for it, so on the one file that must name a mount path, that
10	// barrier is switched off entirely. This rule is what still looks.
11	//
12	// Scope: the wiring files that may legitimately spell a mount path (CLAUDE.md,
13	// .claude/, .github/workflows/, the settings file) plus this repo's own local
14	// packs. Files under .claudinite/shared/ are the vendored canon talking about
15	// itself — not ours to police.
16	const SHARED = '.claudinite/shared/';
17	const TEXT = /\.(md|json|ya?ml|sh|mjs|js|py|dart)$/;
18	const REF = /\.claudinite\/[A-Za-z0-9_./-]+/g;
19	
20	// A reference resolves if the mount holds it as a tracked file or as a directory
21	// of one (CLAUDE.md points at `.claudinite/local/packs/hello-world-flutter/`).
22	const resolver = (tracked) => {
23	  const files = new Set(tracked);
24	  const dirs = new Set();
25	  for (const f of tracked) {
26	    const parts = f.split('/');
27	    for (let i = 1; i < parts.length; i += 1) dirs.add(parts.slice(0, i).join('/'));
28	  }
29	  return (p) => files.has(p) || dirs.has(p);
30	};
31	
32	const rule = {
33	  id: 'hello-world-flutter/mount-path-exists',
34	  severity: 'blocking',
35	  description: 'Every .claudinite/ path this repo names in its own files must resolve in the mount',
36	  doc: '.claudinite/local/packs/hello-world-flutter/RULES.md',
37	  why: 'the canon relays out its own paths on every baseline and never rewrites our references; a stale one misdirects the manual Setup-script paste that is the only thing putting Flutter in a cloud session, and claudinite-isolation is accepted on CLAUDE.md so nothing else looks at it',
38	
39	  run(ctx) {
40	    const resolves = resolver(ctx.tracked);
41	    // Mount absent (a checkout without the vendored canon): only our own local
42	    // packs are verifiable, so leave shared/ references alone rather than
43	    // flooding the sweep with findings about files that were never fetched.
44	    const mounted = ctx.tracked.some((f) => f.startsWith(SHARED));
45	
46	    const out = [];
47	    for (const file of ctx.tracked) {
48	      if (file.startsWith(SHARED) || !TEXT.test(file)) continue;
49	      const text = ctx.read(file);
50	      if (text === null) continue;
51	
52	      const seen = new Set();
53	      for (const m of text.matchAll(REF)) {
54	        // A trailing slash (a directory) or sentence period is punctuation, not path.
55	        const path = m[0].replace(/[./]+$/, '');
56	        if (seen.has(path)) continue;
57	        seen.add(path);
58	        if (!mounted && path.startsWith(SHARED)) continue;
59	        if (resolves(path)) continue;
60	        out.push(finding(rule, {
61	          file,
62	          line: lineOf(text, new RegExp(path.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))),
63	          what: `names \`${path}\`, which is not in the mount`,
64	          fix: "find the path's current home under the mount and update the reference — and the matching `accept` reason in .claudinite-checks.json if it quotes the old path",
65	        }));
66	      }
67	    }
68	    return out;
69	  },
70	};
71	
72	export default rule;
