1	import { sep } from 'node:path';
2	import { finding } from '../../engine/checks/helpers/findings.mjs';
3	import { LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR } from '../../engine/pack_loader/pack-registry.mjs';
4	
5	// The machine backstop for the growth-dedup task doc's rule: a dedup edit only ever REMOVES
6	// portable text. The routine has instead reworded partially-covered items —
7	// leading with a "this rule is portable (canon)" meta-line and re-stating the
8	// now-canon rule (and which pack owns it) inside the local pack — which grows
9	// the entry and duplicates canon prose, the inverse of dedup. Two independent
10	// signals catch that:
11	//
12	//  (1) Canon-restatement fingerprint. An ADDED local-pack prose line that says
13	//      a rule "is portable (canon)", that a "pack owns" a rule, or that the
14	//      canon "owns" it, is re-importing the canon into the local pack. This is
15	//      a corruption on any branch, dedup-labeled or not, so it is unscoped. The
16	//      legitimate delegation convention ("(canon): here <residue>") names the
17	//      canon without any of these phrasings, so it is not matched.
18	//
19	//  (2) A dedup run must SHRINK the pack it prunes. Scoped to a run whose commits
20	//      announce a dedup (extract legitimately GROWS a pack, so the shrink
21	//      invariant can't be unscoped): a modified local-pack prose file whose head
22	//      has more lines than its base grew instead of pruning.
23	//
24	//      A commit message saying "dedup" is not enough on its own — a change that
25	//      FIXES the dedup routine says "dedup" too, and it edits the canon while
26	//      touching a local pack, which reads as a corrupt prune. So the shrink
27	//      invariant also requires the branch to be CONFINED to the local-pack
28	//      surface, which a real run always is: the routine's own first prohibition
29	//      is that it never edits the canon it prunes against. A branch reaching
30	//      outside local packs is canon work that merely mentions dedup.
31	//
32	// Local packs live under either root during the rename transition; git emits
33	// '/'-separated paths, so the platform-joined constants are normalized.
34	const LOCAL_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
35	  .map((s) => `${s.split(sep).join('/')}/`);
36	
37	const isLocalPackProse = (file) =>
38	  file.endsWith('.md') && LOCAL_ROOTS.some((root) => file.startsWith(root));
39	
40	const RESTATES_CANON = /\b(?:is|are) portable\s*\(canon\)|\bpack owns\b|\bcanon (?:now )?owns\b|\bowned by (?:the )?canon\b/i;
41	const DEDUP_RUN = /\bdedup\b|\bcanon now (?:covers|owns)\b/i;
42	
43	const rule = {
44	  id: 'dedup-prune-integrity',
45	  severity: 'blocking',
46	  scope: 'work',
47	  doc: 'packs/grow_with_claudinite/tasks/growth-dedup/task.md',
48	  description: 'A dedup edit only removes portable text — it never grows a local pack or re-imports a canon rule into it',
49	  why: 'the growth-dedup routine has reworded partially-covered items instead of stripping them — restating the canon rule inside the local pack, the inverse of dedup — and every dedup edit must shrink the pack, not grow it',
50	
51	  run(work) {
52	    if (work.onDefaultBranch()) return [];
53	    const prose = work.changedFiles.filter(isLocalPackProse);
54	    if (!prose.length) return [];
55	    const findings = [];
56	
57	    // (1) Canon-restatement fingerprint — unscoped: no legitimate edit re-imports
58	    // a canon rule into a local pack.
59	    for (const { file, line, text } of work.addedLines(prose)) {
60	      if (RESTATES_CANON.test(text)) {
61	        findings.push(finding(rule, {
62	          file,
63	          line,
64	          what: `local-pack prose re-imports a canon rule: "${text.trim().slice(0, 80)}"`,
65	          fix: 'delegate the portable rule to the canon and keep only this project\'s residue — never restate the canon rule, its fix, or which pack owns it (use the pack\'s "(canon): here …" convention)',
66	        }));
67	      }
68	    }
69	
70	    // (2) A dedup run must shrink the pack it prunes, never grow it.
71	    const isDedupRun = work.commits.some((m) => DEDUP_RUN.test(m)) &&
72	      work.changedFiles.every((f) => LOCAL_ROOTS.some((root) => f.startsWith(root)));
73	    if (isDedupRun) {
74	      for (const file of prose) {
75	        const base = work.readBase(file);
76	        const head = work.read(file);
77	        // A file absent at base (new pack) or gone at head (whole-file prune)
78	        // did not grow — only a modified-in-place file can.
79	        if (base === null || head === null) continue;
80	        const baseLines = base.split('\n').length;
81	        const headLines = head.split('\n').length;
82	        if (headLines > baseLines) {
83	          findings.push(finding(rule, {
84	            file,
85	            what: `a dedup run grew ${file} from ${baseLines} to ${headLines} lines — a prune/strip removes duplicated text, it never grows the pack`,
86	            fix: 'strip each covered item down to its project residue (a deletion that shrinks the entry); if you are keeping an item, leave it unchanged rather than rewording it',
87	          }));
88	        }
89	      }
90	    }
91	
92	    return findings;
93	  },
94	};
95	
96	export default rule;
97

// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
// DESIGN §1, §5.5). The executor runs this in code AFTER the subagent finishes:
// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
// task that opened a PR — or an `open-pr` task that merged one — fails the run
// and converges to needs-human. "No change" is always legal.
//
// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
// what the task did to PULL REQUESTS.

import { OUTCOMES } from './task-contract.mjs';

// Verify what a task actually did against its declared ceiling.
//   outcome    — the task's declared ceiling ('none' | 'open-pr' | 'merged-pr')
//   openedPr   — did the run open a pull request?
//   mergedPr   — did the run merge (or arm auto-merge on) a pull request?
// Returns { ok, violation } — violation is null when within the ceiling.
export function verifyOutcome({ outcome, openedPr = false, mergedPr = false }) {
  if (!OUTCOMES.includes(outcome)) {
    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
  }
  // Merging implies a PR exists; treat a merge as also having opened one so a
  // caller that only reports mergedPr is still judged correctly.
  const opened = openedPr || mergedPr;

  if (outcome === 'none' && opened) {
    return { ok: false, violation: 'a "none" task must not open or merge a pull request' };
  }
  if (outcome === 'open-pr' && mergedPr) {
    return { ok: false, violation: 'an "open-pr" task must not merge a pull request' };
  }
  return { ok: true, violation: null };
}

